INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l10','draw on','',NULL,'/drɔː ɑːn/','Engineers draw on their home languages.','工程师借助家乡的语言。','She drew on years of experience.','她凭借多年的经验。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l10','make up','',NULL,'/meɪk ʌp/','Immigrant engineers make up a large share of the staff.','移民工程师占员工的很大一部分。','Women make up half the class.','女生占全班的一半。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l10','thrive on','',NULL,'/θraɪv ɑːn/','The industry thrives on anarchy.','这个行业靠无政府状态蓬勃发展。','She thrives on a challenge.','她越有挑战越来劲。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l10','set up','',NULL,'/set ʌp/','She set up a small factory abroad.','她在海外办起一家小厂。','They set up a new company.','他们创办了一家新公司。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp1','choice','{"stem":"\"The next wave ___ carry the Valley back to its roots.\"(表‘可能、也许’的情态词)","options":["must","may","dare","need"],"answer_index":1,"stem_cn":"下一波浪潮可能把硅谷带回它的根源。","explanation_cn":"表“可能、也许”用情态词 may。✓ The next wave may carry the Valley back. ✗ must(必然)/ need / dare:表“可能”用 may。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp1','choice','{"stem":"\"Many engineers ___ draw on their home languages.\"(表‘能够’的情态词)","options":["ought","must","should","can"],"answer_index":3,"stem_cn":"许多工程师能借助家乡的语言。","explanation_cn":"表“能够”用情态词 can。✓ Many engineers can draw on their home languages. ✗ must / should / ought:表“能够”用 can。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp1','choice','{"stem":"\"Silicon Valley ___ yet prove a great classroom.\"(表‘可能仍会’,填情态词)","options":["may","used","dare","need"],"answer_index":0,"stem_cn":"硅谷或许还会证明自己是一所了不起的学校。","explanation_cn":"表“可能仍会”用 may。✓ Silicon Valley may yet prove a great classroom. ✗ need / dare / used:表“可能”用 may。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp2','choice','{"stem":"\"There are workstations ___ let engineers make chips at their desks.\"(定语从句,指物作主语)","options":["who","what","that","whose"],"answer_index":2,"stem_cn":"如今有工作站可让工程师在自己桌上造芯片。","explanation_cn":"定语从句先行词 workstations(物),关系词在从句中作主语,用 that。✓ workstations that let engineers make chips. ✗ who(指人)/ what / whose:指物作主语用 that。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp2','choice','{"stem":"\"The new tools ___ engineers to test a chip in days.\"(‘使某人能够做…’,填这个使役动词)","options":["prevent","enable","refuse","forbid"],"answer_index":1,"stem_cn":"新工具使工程师能在几天内测试一枚芯片。","explanation_cn":"“使某人能够做…”=enable sb to do。✓ The new tools enable engineers to test a chip. ✗ prevent 阻止;✗ forbid 禁止;✗ refuse 拒绝——都相反或不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp2','choice','{"stem":"\"A workstation lets one engineer ___ a chip alone.\"(let sb do,填动词原形)","options":["to design","designing","design","designs"],"answer_index":2,"stem_cn":"工作站让一名工程师独自设计芯片。","explanation_cn":"let sb do:let 后接动词原形(不带 to)。✓ A workstation lets one engineer design a chip. ✗ designs / designing / to design:let 后用原形 design。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp3','choice','{"stem":"\"Engineers can experiment without ___ penalized for failure.\"(without + ___ + 过去分词表被动,填中间的词)","options":["been","be","to be","being"],"answer_index":3,"stem_cn":"工程师可以放手试验而不因失败受罚。","explanation_cn":"without 是介词,后接动名词;表被动用 being + 过去分词;中间那个词是 being。✓ without being penalized. ✗ be / been / to be:被动动名词用 being + 过去分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp3','choice','{"stem":"\"He left without ___ a word to anyone.\"(without + 动名词,填 -ing 形式)","options":["saying","say","said","to say"],"answer_index":0,"stem_cn":"他一句话没说就走了。","explanation_cn":"without + 动名词;say 的 -ing 是 saying。✓ He left without saying a word. ✗ said / say / to say:介词后用动名词 saying。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp3','choice','{"stem":"\"The chip was improved without ___ much money.\"(without + 动名词,填 -ing 形式)","options":["cost","costs","costing","to cost"],"answer_index":2,"stem_cn":"这枚芯片没花多少钱就得到了改进。","explanation_cn":"without + 动名词;cost 的 -ing 是 costing。✓ improved without costing much money. ✗ cost / costs / to cost:介词后用动名词 costing。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp4','choice','{"stem":"\"___ the cost of a chip falls, engineers grow bolder.\"(‘随着…’,填连词)","options":["Unless","Though","If","As"],"answer_index":3,"stem_cn":"随着芯片成本下降,工程师变得更大胆。","explanation_cn":"表“随着…”用连词 As。✓ As the cost falls, engineers grow bolder. ✗ If(如果)/ Unless(除非)/ Though(尽管):表“随着”用 As。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp4','choice','{"stem":"\"___ time goes on, the Valley keeps reinventing itself.\"(‘随着时间推移’,填连词)","options":["Before","Whether","As","Because"],"answer_index":2,"stem_cn":"随着时间推移,硅谷不断自我重塑。","explanation_cn":"表“随着时间推移”用 As。✓ As time goes on, the Valley reinvents itself. ✗ Because / Before / Whether:表“随着”用 As。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp4','choice','{"stem":"\"Costs drop ___ the technology improves.\"(‘随着…’,填连词)","options":["as","although","unless","until"],"answer_index":0,"stem_cn":"随着技术进步,成本随之下降。","explanation_cn":"表“随着…”用 as。✓ Costs drop as the technology improves. ✗ until / unless / although:表“随着”用 as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp5','choice','{"stem":"\"Inventors perfect chips fast, ___ a wave of start-ups.\"(现在分词作结果状语,主动‘催生’)","options":["spawned","to spawn","spawning","spawn"],"answer_index":2,"stem_cn":"发明者迅速完善芯片,催生了一波创业潮。","explanation_cn":"现在分词作结果状语,主动“催生”。✓ Inventors perfect chips fast, spawning start-ups. ✗ spawned(被动/过去)/ spawn / to spawn:主动结果用 -ing。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp5','choice','{"stem":"\"The new speed helps them, ___ the country a real lead.\"(现在分词作结果状语,主动‘给予’)","options":["give","giving","given","to give"],"answer_index":1,"stem_cn":"新的速度帮了他们,给了这个国家实实在在的领先。","explanation_cn":"现在分词作结果状语,主动“给予”。✓ The new speed helps them, giving the country a lead. ✗ given / give / to give:主动结果用 -ing。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp5','choice','{"stem":"\"They share their skills, ___ links with distant markets.\"(现在分词作结果状语,主动‘建立’)","options":["forged","forge","forging","to forge"],"answer_index":2,"stem_cn":"他们分享技能,与遥远的市场建立起联系。","explanation_cn":"现在分词作结果状语,主动“建立”。✓ They share their skills, forging links. ✗ forged / forge / to forge:主动结果用 -ing。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp6','choice','{"stem":"\"A small piece of silicon holding a circuit is a ___.\"(“芯片”用哪个词)","options":["brick","leaf","coin","chip"],"answer_index":3,"stem_cn":"承载电路的一小片硅。","explanation_cn":"承载电路的一小片硅是 chip(芯片)。✓ a small piece of silicon holding a circuit is a chip. ✗ brick 砖;✗ coin 硬币;✗ leaf 叶——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp6','choice','{"stem":"\"When a business grows well and succeeds, it ___.\"(“兴旺、蓬勃发展”用哪个词)","options":["shrinks","thrives","closes","fails"],"answer_index":1,"stem_cn":"生意红火、蓬勃发展。","explanation_cn":"生意红火、蓬勃发展用 thrive。✓ When a business succeeds, it thrives. ✗ fails 失败;✗ closes 关闭;✗ shrinks 萎缩——都相反。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',5,'am4_l10_gp6','choice','{"stem":"\"A state with no government or order is in ___.\"(“无政府、混乱”用哪个词)","options":["peace","harmony","anarchy","order"],"answer_index":2,"stem_cn":"没有政府或秩序的状态。","explanation_cn":"没有政府或秩序的状态是 anarchy(无政府状态)。✓ a state with no order is in anarchy. ✗ harmony 和谐;✗ order 秩序;✗ peace 和平——都相反。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',6,NULL,'choice','{"stem":"silicon 的意思是:","options":["金","铜","硅","铁"],"answer_index":2,"explanation_cn":"silicon = 硅。✓ Silicon Valley 硅谷。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',6,NULL,'choice','{"stem":"thrive 的意思是:","options":["兴旺,繁荣","停止","衰败","隐藏"],"answer_index":0,"explanation_cn":"thrive = 兴旺、繁荣。✓ thrived on a kind of cheerful anarchy."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',6,NULL,'choice','{"stem":"anarchy 的意思是:","options":["秩序","和平","无政府状态,混乱","法律"],"answer_index":2,"explanation_cn":"anarchy = 无政府状态、混乱。✓ a kind of cheerful anarchy."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',6,NULL,'choice','{"stem":"innovator 的意思是:","options":["革新者,创新者","破坏者","旁观者","追随者"],"answer_index":0,"explanation_cn":"innovator = 革新者、创新者。✓ one young innovator."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',6,NULL,'choice','{"stem":"forge 的意思是:","options":["丢失","摧毁","打造,建立","隐藏"],"answer_index":2,"explanation_cn":"forge = 打造、建立(纽带)。✓ to forge stronger links."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',6,NULL,'choice','{"stem":"spawn 的意思是:","options":["推迟","减少","结束","引发,催生"],"answer_index":3,"explanation_cn":"spawn = 引发、催生。✓ spawning a fresh generation of start-ups."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',7,NULL,'cloze','{"stem":"第 1 空","context":"There are workstations ___1___ let engineers make chips at their desks. ___2___ the cost falls, they grow bolder and can experiment without ___3___ penalized. Inventors perfect designs fast, ___4___ many new start-ups.","blank_no":1,"options":["that","who","what","whose"],"answer_index":0,"explanation_cn":"定语从句指物(workstations)作主语,用 that。✓ workstations that let engineers make chips."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',7,NULL,'cloze','{"stem":"第 2 空","context":"There are workstations ___1___ let engineers make chips at their desks. ___2___ the cost falls, they grow bolder and can experiment without ___3___ penalized. Inventors perfect designs fast, ___4___ many new start-ups.","blank_no":2,"options":["As","If","Unless","Though"],"answer_index":0,"explanation_cn":"表“随着…”用 As。✓ As the cost falls, they grow bolder."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',7,NULL,'cloze','{"stem":"第 3 空","context":"There are workstations ___1___ let engineers make chips at their desks. ___2___ the cost falls, they grow bolder and can experiment without ___3___ penalized. Inventors perfect designs fast, ___4___ many new start-ups.","blank_no":3,"options":["being","be","been","to be"],"answer_index":0,"explanation_cn":"without + being + 过去分词表被动。✓ without being penalized."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',7,NULL,'cloze','{"stem":"第 4 空","context":"There are workstations ___1___ let engineers make chips at their desks. ___2___ the cost falls, they grow bolder and can experiment without ___3___ penalized. Inventors perfect designs fast, ___4___ many new start-ups.","blank_no":4,"options":["spawning","spawned","spawn","to spawn"],"answer_index":0,"explanation_cn":"现在分词作结果状语,主动“催生”。✓ perfect designs fast, spawning many start-ups."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',8,NULL,'choice','{"stem":"According to the talk, what does the computer industry thrive on?","options":["Strict rules and central planning","A kind of cheerful anarchy and clever people in garages","Cheap foreign labor only","Government control"],"answer_index":1,"explanation_cn":"录音说这个行业靠一种愉快的无政府状态、以及大量车库里的聪明人蓬勃发展。✓ cheerful anarchy + clever people."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',8,NULL,'choice','{"stem":"What do the new workstations let a single engineer do?","options":["Design, test, and produce a chip at her own desk","Only send email","Manage a whole factory by hand","Replace all software"],"answer_index":0,"explanation_cn":"录音说新工作站让一名工程师能在自己桌前设计、测试并造出一枚芯片。✓ design, test, produce at one desk."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',8,NULL,'choice','{"stem":"Why may engineers soon feel free to experiment?","options":["Failure will be forbidden","The government will pay them","Chips will no longer be needed","Making a chip will cost little time and money"],"answer_index":3,"explanation_cn":"录音说随着造芯片的时间和金钱大幅下降,工程师很快便能放手试验。✓ little time and money."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',9,NULL,'choice','{"stem":"你想说\"下一波浪潮可能把硅谷带回它的根源\"(情态词表可能):","options":["The next wave may carries the Valley back to its roots.","The next wave may to carry the Valley back to its roots.","The next wave carry may the Valley back to its roots.","The next wave may carry the Valley back to its roots."],"answer_index":3,"explanation_cn":"情态词 may 后接动词原形 carry(不加 s、不加 to、语序不颠倒)。✓ may carry. 场合:说“也许会…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',9,NULL,'choice','{"stem":"你想说\"工程师可以放手试验而不因失败受罚\"(without + 动名词被动):","options":["Engineers can experiment without being penalized for failure.","Engineers can experiment without being penalize for failure.","Engineers can experiment without penalized for failure.","Engineers can experiment without be penalized for failure."],"answer_index":0,"explanation_cn":"without 后接动名词,被动用 being + 过去分词 penalized;不用原形 be、不省 being、penalized 不写成 penalize。✓ without being penalized. 场合:说“做某事而不被…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',9,NULL,'choice','{"stem":"你想说\"随着芯片成本下降,工程师变得更大胆\"(As 随着):","options":["While the cost of a chip falls, engineers grows bolder.","As the cost of a chip falls, engineers grow bolder.","As the cost of a chip fall, engineers grow bolder.","As the cost of a chip falls, engineers growing bolder."],"answer_index":1,"explanation_cn":"As 引导“随着…”;从句动词随单数 the cost 用 falls、主句 engineers 用 grow(不加 -ing)。✓ As … falls, engineers grow bolder. 场合:说“随着…,就…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"silicon 的意思是:","options":["金","铜","硅","铁"],"answer_index":2,"explanation_cn":"silicon = 硅。✓ Silicon Valley."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"anarchy 的意思是:","options":["秩序","无政府状态,混乱","法律","和平"],"answer_index":1,"explanation_cn":"anarchy = 无政府状态、混乱。✓ a kind of cheerful anarchy."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"\"The next wave ___ carry the Valley back to its roots.\"(情态词表‘可能’)","options":["dare","used","may","need"],"answer_index":2,"stem_cn":"下一波浪潮可能把硅谷带回它的根源。","explanation_cn":"表“可能、也许”用情态词 may。✓ The next wave may carry the Valley back. ✗ need / dare / used。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"\"Engineers can experiment without ___ penalized.\"(without + ___ + 过去分词)","options":["to be","being","be","been"],"answer_index":1,"stem_cn":"工程师可以放手试验而不受罚。","explanation_cn":"without + being + 过去分词表被动。✓ without being penalized. ✗ be / been / to be。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"\"thrive on\" 的意思是:","options":["忽视","逃离","讨厌","靠…蓬勃发展、以…为动力"],"answer_index":3,"explanation_cn":"thrive on = 靠…蓬勃发展、以…为动力。✓ thrives on anarchy."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"\"draw on\" 的意思是:","options":["利用、借助","睡着","拒绝","丢弃"],"answer_index":0,"explanation_cn":"draw on = 利用、借助。✓ draw on their home languages."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"What do the new workstations allow a single engineer to do?","options":["Only print newsletters","Design, test, and customize a chip at one desk","Replace every other worker","Run the entire company alone"],"answer_index":1,"passage":"Some who watch the technology closely believe that the next wave may carry Silicon Valley back toward its restless beginnings. Dr. Elena Ross, a veteran of the early chip labs and now a professor of computer science, points out that there are now workstations that let a single engineer design, test, and customize a chip right at her own desk, much the way a writer lays out a newsletter on a laptop. As the time and money needed to make a chip fall to a few days and a few hundred dollars, engineers may soon be free to let their imaginations run wild without being penalized for every costly failure. Ross predicts that inventors will be able to perfect a bold new design over a single weekend, spawning a fresh generation of garage start-ups and giving the country a real jump on its foreign rivals in the race to market. \"We''ve still got plenty of garages full of clever people,\" she says. \"This industry has always thrived on a kind of cheerful anarchy.\" Newcomers matter, too. Engineers born all over the world now make up a large share of the Valley''s staff, and many can draw on the customs and languages of their home regions to forge stronger links with distant markets. One young innovator, trained at a local university, has already set up a small factory abroad to challenge an old giant''s grip on the memory-chip business. Before it ever settles into a quiet retirement, Silicon Valley may yet prove a classroom for building companies that reach around the globe.","explanation_cn":"课文说新工作站让一名工程师能在一张桌上设计、测试并定制一枚芯片。✓ design, test, customize at one desk."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"Why might inventors soon experiment more boldly?","options":["Making a chip will take little time and money","Chips will become unnecessary","The government will fund every idea","Failures will be banned by law"],"answer_index":0,"passage":"Some who watch the technology closely believe that the next wave may carry Silicon Valley back toward its restless beginnings. Dr. Elena Ross, a veteran of the early chip labs and now a professor of computer science, points out that there are now workstations that let a single engineer design, test, and customize a chip right at her own desk, much the way a writer lays out a newsletter on a laptop. As the time and money needed to make a chip fall to a few days and a few hundred dollars, engineers may soon be free to let their imaginations run wild without being penalized for every costly failure. Ross predicts that inventors will be able to perfect a bold new design over a single weekend, spawning a fresh generation of garage start-ups and giving the country a real jump on its foreign rivals in the race to market. \"We''ve still got plenty of garages full of clever people,\" she says. \"This industry has always thrived on a kind of cheerful anarchy.\" Newcomers matter, too. Engineers born all over the world now make up a large share of the Valley''s staff, and many can draw on the customs and languages of their home regions to forge stronger links with distant markets. One young innovator, trained at a local university, has already set up a small factory abroad to challenge an old giant''s grip on the memory-chip business. Before it ever settles into a quiet retirement, Silicon Valley may yet prove a classroom for building companies that reach around the globe.","explanation_cn":"课文说随着造芯片的时间和金钱降到很低,发明者便能更大胆地试验。✓ little time and money."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"What does the industry thrive on, in Dr. Ross''s view?","options":["Slow careful planning","Foreign tariffs","A cheerful sort of anarchy","Strict central control"],"answer_index":2,"audio":"Some who watch the technology closely believe that the next wave may carry Silicon Valley back toward its restless beginnings. Dr. Elena Ross, a veteran of the early chip labs and now a professor of computer science, points out that there are now workstations that let a single engineer design, test, and customize a chip right at her own desk, much the way a writer lays out a newsletter on a laptop. As the time and money needed to make a chip fall to a few days and a few hundred dollars, engineers may soon be free to let their imaginations run wild without being penalized for every costly failure. Ross predicts that inventors will be able to perfect a bold new design over a single weekend, spawning a fresh generation of garage start-ups and giving the country a real jump on its foreign rivals in the race to market. \"We''ve still got plenty of garages full of clever people,\" she says. \"This industry has always thrived on a kind of cheerful anarchy.\" Newcomers matter, too. Engineers born all over the world now make up a large share of the Valley''s staff, and many can draw on the customs and languages of their home regions to forge stronger links with distant markets. One young innovator, trained at a local university, has already set up a small factory abroad to challenge an old giant''s grip on the memory-chip business. Before it ever settles into a quiet retirement, Silicon Valley may yet prove a classroom for building companies that reach around the globe.","explanation_cn":"录音引罗斯博士的话:这个行业一向靠一种愉快的无政府状态蓬勃发展。✓ cheerful anarchy."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l10',10,NULL,'choice','{"stem":"What advantage do globally born engineers bring?","options":["They forge links with distant markets through their languages and customs","They avoid all new technology","They work for free","They dislike start-ups"],"answer_index":0,"audio":"Some who watch the technology closely believe that the next wave may carry Silicon Valley back toward its restless beginnings. Dr. Elena Ross, a veteran of the early chip labs and now a professor of computer science, points out that there are now workstations that let a single engineer design, test, and customize a chip right at her own desk, much the way a writer lays out a newsletter on a laptop. As the time and money needed to make a chip fall to a few days and a few hundred dollars, engineers may soon be free to let their imaginations run wild without being penalized for every costly failure. Ross predicts that inventors will be able to perfect a bold new design over a single weekend, spawning a fresh generation of garage start-ups and giving the country a real jump on its foreign rivals in the race to market. \"We''ve still got plenty of garages full of clever people,\" she says. \"This industry has always thrived on a kind of cheerful anarchy.\" Newcomers matter, too. Engineers born all over the world now make up a large share of the Valley''s staff, and many can draw on the customs and languages of their home regions to forge stronger links with distant markets. One young innovator, trained at a local university, has already set up a small factory abroad to challenge an old giant''s grip on the memory-chip business. Before it ever settles into a quiet retirement, Silicon Valley may yet prove a classroom for building companies that reach around the globe.","explanation_cn":"录音说来自世界各地的工程师能借家乡语言与习俗,与遥远市场缔结更牢的纽带。✓ forge links via languages and customs."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l11',4,2,11,'How to Grow Old','如何度过晚年','定语从句(who/that,含 the man who…)、what/whatever 引导的名词性从句、since 引导的原因状语从句、if 引导的条件状语从句(含与现在相反的虚拟)、现在分词/形容词作伴随状语(knowing…, glad…)(NCE4 无 KS 页,考点由课文结构自取;IP 最高危:源为伯特兰·罗素极著名散文,其‘个体生命如河流汇入大海’招牌隐喻不复制,已换 100% 原创‘乐曲中一个音符汇入整体和声’隐喻承载同一哲理,只提语法/词表/话题/篇幅;题材=晚年如何看待死亡·平和无害;美语化 realize/honor;第四册第11课)','有些老人被对死亡的恐惧压得喘不过气。在年轻人身上,这种恐惧尚有道理:一个有充分理由担心自己会英年早逝的年轻人,可以理直气壮地感到痛苦,因为他被夺去了生活所能给予的最好的东西。但在一个活得长久、尝过深切欢乐与沉重悲伤、又做完了命中注定该做的一切工作的人身上,同样的恐惧在我看来就显得凄惨而卑下了。克服它最稳妥的办法是这样:让你的兴趣一点一点地变得更宽广、更超脱个人,直到自我的高墙渐渐后退,你那渺小的一生被纳入某种远为宏大的东西之中。一个人的一生应当像一支长曲里的一个音符。起初,那音符独自响着,焦灼而热切,热情地只歌唱它自己。可随着乐曲展开,别的音符加入进来;它不再作为一个孤单的声音被听见,而成了宏大和声的一部分,最终毫无痛苦地融入整体,不带一丝失落。凡是到了晚年能这样聆听自己一生的人,就不会被死亡的恐惧所压迫,因为他所珍视的事物会在他身后延续下去。而如果随着生命力衰退,疲惫渐渐加深,休息的念头也就不会不受欢迎。就我而言,我愿工作到最后一刻,知道别人会接着做我再也做不了的事,并欣慰地想到:凡是我力所能及的,都确实已经做成。','{"q":"Listen and answer — What, according to the author, is the best way to overcome the fear of death as you get older?","options":["Make your interests gradually wider and more impersonal","Try never to think about death","Become rich and famous","Stay indoors and rest"],"answer_index":0}'::jsonb,'{"title":"定语从句 / what 名词从句 / since 原因 / if 条件 / 分词作伴随状语","intro":"①定语从句 who(指人)/ that(指物):a man who has known joys;the things that he cares for。②what/whatever 引导名词从句:what I can no longer do。③since 引导原因:…, since the things will continue。④if 引导条件(可含虚拟 If he were young…)。⑤现在分词/形容词作伴随状语:…, knowing that…；…, glad in the thought that…。","table":{"headers":["用法","结构","例子"],"rows":[["定语从句","who/that + 从句","a man who has known joys"],["what 名词从句","what + 从句","what I can no longer do"],["since 原因","…, since + 从句","since the things will continue"],["if 条件","if + 从句, 主句","If weariness increases, rest is welcome"],["分词伴随状语","…, doing …","…, knowing that others will carry on"]]},"specialRules":[{"rule":"定语从句关系词:指人多用 who,指物用 that/which;作宾语时可省略。","mark":"who / that"},{"rule":"what 引导名词从句时本身在从句里充当成分,相当于 the thing that;不可与 that 互换。","mark":"what = the thing that"},{"rule":"美式拼写:realize(意识到,英式 realise)、honor(荣誉,英式 honour)。本课已按美语写。","mark":"realize / honor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l11',1,NULL,'Some old people are worn down by the fear of death. In the young this dread has a real justification: a young man who has good reason to fear he may be killed before his time can justifiably feel bitter, for he has been robbed of the best that life had to offer.','有些老人被对死亡的恐惧压得喘不过气。在年轻人身上,这种恐惧尚有道理:一个有充分理由担心自己会英年早逝的年轻人,可以理直气壮地感到痛苦,因为他被夺去了生活所能给予的最好的东西。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l11',2,NULL,'But in someone who has lived long, who has known deep joys and heavy sorrows, and who has finished whatever work it was given him to do, the same fear seems to me abject and ignoble.','但在一个活得长久、尝过深切欢乐与沉重悲伤、又做完了命中注定该做的一切工作的人身上,同样的恐惧在我看来就显得凄惨而卑下了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l11',3,NULL,'The surest way to overcome it is this: let your interests grow gradually wider and more impersonal, until, little by little, the walls of the ego begin to recede and your own small life is taken up into something far larger. A single human life should be like one note in a long piece of music.','克服它最稳妥的办法是这样:让你的兴趣一点一点地变得更宽广、更超脱个人,直到自我的高墙渐渐后退,你那渺小的一生被纳入某种远为宏大的东西之中。一个人的一生应当像一支长曲里的一个音符。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l11',4,NULL,'At first the note sounds alone, anxious and eager, singing passionately of itself. But as the music goes on, the note is joined by others; it is no longer heard as one lonely sound but as part of a great harmony, and in the end it fades painlessly into the whole without any sense of loss.','起初,那音符独自响着,焦灼而热切,热情地只歌唱它自己。可随着乐曲展开,别的音符加入进来;它不再作为一个孤单的声音被听见,而成了宏大和声的一部分,最终毫无痛苦地融入整体,不带一丝失落。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l11',5,NULL,'Whoever, in old age, can hear his own life in this way will not be oppressed by the fear of death, since the things he has cared for will go on after him. And if, as his vitality decays, weariness gradually increases, the thought of rest will not be unwelcome. For my part, I should wish to keep working to the last, knowing that others will carry on what I can no longer do, and glad in the thought that what was possible for me has indeed been done.','凡是到了晚年能这样聆听自己一生的人,就不会被死亡的恐惧所压迫,因为他所珍视的事物会在他身后延续下去。而如果随着生命力衰退,疲惫渐渐加深,休息的念头也就不会不受欢迎。就我而言,我愿工作到最后一刻,知道别人会接着做我再也做不了的事,并欣慰地想到:凡是我力所能及的,都确实已经做成。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
