INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l11','toward','towards','朝向;美语常用 toward 不带 s') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l11','marvelous','marvellous','奇妙的;拼写差异,美语单 l') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l11','carry on','',NULL,'/ˈkæri ɑːn/','Others will carry on my work.','别人会继续我的工作。','Please carry on with your reading.','请继续读下去。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l11','little by little','',NULL,'/ˈlɪtl baɪ ˈlɪtl/','Little by little the walls of the ego recede.','自我的高墙一点一点地后退。','She recovered little by little.','她渐渐康复了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l11','care for','',NULL,'/ker fɔːr/','The things he cares for will continue.','他所珍视的事物会延续。','He cares deeply for his students.','他深切关爱他的学生。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l11','wear down','',NULL,'/wer daʊn/','The fear wears him down.','这种恐惧把他压垮。','Years of worry wore her down.','多年的忧虑把她拖垮了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp1','choice','{"stem":"\"A young man ___ fears death in battle may feel bitter.\"(定语从句,指人作主语)","options":["whose","whom","which","who"],"answer_index":3,"stem_cn":"害怕死于战场的年轻人可能感到痛苦。","explanation_cn":"定语从句先行词 man(指人),关系词在从句中作主语,用 who。✓ A young man who fears death. ✗ which(指物)/ whom(作宾语)/ whose(所属):指人作主语用 who。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp1','choice','{"stem":"\"The things ___ he has cared for will go on.\"(定语从句,指物作宾语)","options":["that","whom","who","what"],"answer_index":0,"stem_cn":"他所珍视的事物将会延续。","explanation_cn":"定语从句先行词 the things(指物),关系词作宾语,用 that(也可省略)。✓ the things that he has cared for. ✗ who(指人)/ what / whom:指物用 that。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp1','choice','{"stem":"\"An old man ___ has known joys and sorrows sees death calmly.\"(定语从句,指人作主语)","options":["what","which","who","whose"],"answer_index":2,"stem_cn":"一位历经悲欢的老人能平静看待死亡。","explanation_cn":"定语从句先行词 old man(指人),从句中作主语,用 who。✓ An old man who has known joys and sorrows. ✗ which / what / whose:指人作主语用 who。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp2','choice','{"stem":"\"He finished ___ work it was given him to do.\"(‘无论什么…’引导名词从句)","options":["however","whatever","wherever","whenever"],"answer_index":1,"stem_cn":"他做完了交给他的一切工作。","explanation_cn":"“无论什么…”引导名词从句,用 whatever(=任何…的)。✓ whatever work it was given him to do. ✗ however(无论怎样)/ whenever(无论何时)/ wherever(无论何地):指“无论什么”用 whatever。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp2','choice','{"stem":"\"Others will carry on ___ I can no longer do.\"(名词从句,‘所…的事’,填关系词)","options":["that","which","how","what"],"answer_index":3,"stem_cn":"别人会接着做我再也做不了的事。","explanation_cn":"名词从句“所…的事”,what=the thing that,本身在从句里充当成分。✓ carry on what I can no longer do. ✗ that(不引导名词从句作宾语的‘所…的’)/ which / how:用 what。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp2','choice','{"stem":"\"He is glad that ___ was possible has been done.\"(名词从句作主语,‘所…的’)","options":["that","what","which","it"],"answer_index":1,"stem_cn":"他欣慰于凡是可能做到的都已做成。","explanation_cn":"名词从句作主语,“所…的”,what=the thing that。✓ what was possible has been done. ✗ that / which / it:用 what。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp3','choice','{"stem":"\"He will not fear death, ___ his interests will continue.\"(‘既然/因为’,填连词)","options":["since","unless","before","though"],"answer_index":0,"stem_cn":"他不会惧怕死亡,因为他所关心的事会延续。","explanation_cn":"“既然/因为”引导原因,用 since。✓ He will not fear death, since his interests will continue. ✗ unless(除非)/ though(尽管)/ before(之前):表原因用 since。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp3','choice','{"stem":"\"The old man feels calm, ___ he has done his work.\"(‘因为’,填连词)","options":["until","since","unless","whether"],"answer_index":1,"stem_cn":"老人感到安宁,因为他已完成了自己的工作。","explanation_cn":"“因为”引导原因,用 since。✓ feels calm, since he has done his work. ✗ unless / whether / until:表原因用 since。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp3','choice','{"stem":"\"___ others will go on after him, he faces death calmly.\"(句首‘因为’,填连词)","options":["Although","Unless","Since","Whether"],"answer_index":2,"stem_cn":"因为后人会继续他的事业,他从容面对死亡。","explanation_cn":"句首“因为”,用 Since。✓ Since others will go on after him, he faces death calmly. ✗ Unless / Although / Whether:表原因用 Since。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp4','choice','{"stem":"\"___ weariness increases, the thought of rest is welcome.\"(‘如果’,填连词)","options":["Unless","If","Since","Though"],"answer_index":1,"stem_cn":"如果疲惫加深,休息的念头便受欢迎。","explanation_cn":"“如果”引导条件,用 If。✓ If weariness increases, the thought of rest is welcome. ✗ Since / Though / Unless:表条件用 If。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp4','choice','{"stem":"\"The fear fades ___ your interests grow wider.\"(‘如果/只要’,填连词)","options":["if","than","until","unless"],"answer_index":0,"stem_cn":"只要你的兴趣变得更广,恐惧就会消退。","explanation_cn":"“如果/只要”引导条件,用 if。✓ The fear fades if your interests grow wider. ✗ unless(除非)/ until / than:表条件用 if。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp4','choice','{"stem":"\"___ he were young, the fear might be justified.\"(与现在相反的虚拟条件,填条件连词)","options":["When","If","As","Since"],"answer_index":1,"stem_cn":"假如他还年轻,这种恐惧或许还情有可原。","explanation_cn":"与现在相反的虚拟条件,从句用 were;条件连词用 If。✓ If he were young, the fear might be justified. ✗ As / Since / When:虚拟条件用 If。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp5','choice','{"stem":"\"He wished to die at work, ___ that others would continue.\"(现在分词作伴随状语,主动‘知道’)","options":["know","known","to know","knowing"],"answer_index":3,"stem_cn":"他愿意工作到最后,知道别人会继续下去。","explanation_cn":"现在分词作伴随状语,表主动“知道”。✓ He wished to die at work, knowing that others would continue. ✗ known(被动)/ know / to know:主动伴随用 -ing。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp5','choice','{"stem":"\"She faced the end calmly, ___ in the thought of a full life.\"(形容词作伴随状语,‘感到欣慰的’)","options":["gladly","gladden","glad","gladness"],"answer_index":2,"stem_cn":"她平静面对结局,欣慰于自己度过了充实的一生。","explanation_cn":"形容词作伴随状语,“感到欣慰的”。✓ She faced the end calmly, glad in the thought… ✗ gladly(副词)/ gladness(名词)/ gladden(动词):此处用形容词 glad。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp5','choice','{"stem":"\"The note sang on, ___ passionately of itself.\"(现在分词作伴随状语,主动‘歌唱’)","options":["to sing","sung","sang","singing"],"answer_index":3,"stem_cn":"那音符继续唱着,热切地歌唱自己。","explanation_cn":"现在分词作伴随状语,表主动“歌唱”。✓ The note sang on, singing passionately of itself. ✗ sung(被动)/ sang(过去式)/ to sing:主动伴随用 -ing。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp6','choice','{"stem":"\"To weigh someone down and trouble them is to ___ them.\"(“压迫、使烦恼”用哪个词)","options":["oppress","delight","free","praise"],"answer_index":0,"stem_cn":"沉重地压着、使某人苦恼。","explanation_cn":"沉重地压着、使人苦恼是 oppress(压迫)。✓ to weigh someone down is to oppress them. ✗ delight 使高兴;✗ free 解放;✗ praise 赞美——都相反或不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp6','choice','{"stem":"\"Feeling low, hopeless and miserable is feeling ___.\"(“凄惨的、卑下的”用哪个词)","options":["proud","cheerful","abject","calm"],"answer_index":2,"stem_cn":"极其凄惨、低贱的感觉。","explanation_cn":"极其凄惨、低贱的是 abject。✓ feeling low and miserable is feeling abject. ✗ proud 骄傲;✗ cheerful 快乐;✗ calm 平静——都相反。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',5,'am4_l11_gp6','choice','{"stem":"\"Energy and liveliness of body and mind is ___.\"(“活力、生命力”用哪个词)","options":["vitality","silence","boredom","weakness"],"answer_index":0,"stem_cn":"身心的活力与生命力。","explanation_cn":"身心的活力与生命力是 vitality。✓ energy and liveliness is vitality. ✗ weakness 虚弱;✗ silence 沉默;✗ boredom 无聊——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',6,NULL,'choice','{"stem":"oppress 的意思是:","options":["压迫,使烦恼","赞美","取悦","解放"],"answer_index":0,"explanation_cn":"oppress = 压迫、使烦恼。✓ will not be oppressed by the fear of death."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',6,NULL,'choice','{"stem":"abject 的意思是:","options":["快乐的","高贵的","勇敢的","凄惨的,卑下的"],"answer_index":3,"explanation_cn":"abject = 凄惨的、卑下的。✓ the fear seems abject and ignoble."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',6,NULL,'choice','{"stem":"impersonal 的意思是:","options":["客观的,不带个人感情的","私人的","激动的","亲切的"],"answer_index":0,"explanation_cn":"impersonal = 超脱个人的、客观的。✓ wider and more impersonal."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',6,NULL,'choice','{"stem":"recede 的意思是:","options":["前进","爆发","上升","后退,减弱"],"answer_index":3,"explanation_cn":"recede = 后退、渐远。✓ the walls of the ego begin to recede."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',6,NULL,'choice','{"stem":"vitality 的意思是:","options":["活力,生命力","黑暗","沉默","疲惫"],"answer_index":0,"explanation_cn":"vitality = 活力、生命力。✓ as his vitality decays."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',6,NULL,'choice','{"stem":"ignoble 的意思是:","options":["勇敢的","卑劣的,不光彩的","高尚的","慷慨的"],"answer_index":1,"explanation_cn":"ignoble = 卑劣的、不光彩的。✓ abject and ignoble."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',7,NULL,'cloze','{"stem":"第 1 空","context":"A young man ___1___ fears death in battle may feel bitter. But an old man will not be ___2___ by that fear, ___3___ the things he cares for will go on. Others will carry on ___4___ he can no longer do.","blank_no":1,"options":["who","which","what","whose"],"answer_index":0,"explanation_cn":"定语从句指人(a young man)作主语,用 who。✓ A young man who fears death."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',7,NULL,'cloze','{"stem":"第 2 空","context":"A young man ___1___ fears death in battle may feel bitter. But an old man will not be ___2___ by that fear, ___3___ the things he cares for will go on. Others will carry on ___4___ he can no longer do.","blank_no":2,"options":["oppressed","oppress","oppressing","oppresses"],"answer_index":0,"explanation_cn":"be oppressed by:被…压迫;用过去分词 oppressed。✓ will not be oppressed by that fear."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',7,NULL,'cloze','{"stem":"第 3 空","context":"A young man ___1___ fears death in battle may feel bitter. But an old man will not be ___2___ by that fear, ___3___ the things he cares for will go on. Others will carry on ___4___ he can no longer do.","blank_no":3,"options":["since","unless","though","before"],"answer_index":0,"explanation_cn":"“因为”引导原因,用 since。✓ since the things he cares for will go on."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',7,NULL,'cloze','{"stem":"第 4 空","context":"A young man ___1___ fears death in battle may feel bitter. But an old man will not be ___2___ by that fear, ___3___ the things he cares for will go on. Others will carry on ___4___ he can no longer do.","blank_no":4,"options":["what","that","which","how"],"answer_index":0,"explanation_cn":"名词从句“所…的事”,用 what。✓ carry on what he can no longer do."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',8,NULL,'choice','{"stem":"According to the speaker, what is the best way to overcome the fear of death in old age?","options":["To gain great wealth","To avoid thinking about it entirely","To make your interests gradually wider and more impersonal","To stay physically young"],"answer_index":2,"explanation_cn":"录音说克服晚年怕死的最好办法,是让兴趣逐渐变得更宽广、更超脱个人。✓ wider and more impersonal."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',8,NULL,'choice','{"stem":"What does the speaker compare a single human life to?","options":["A burning house","One note in a long piece of music","A closed book","A lonely mountain"],"answer_index":1,"explanation_cn":"录音把一个人的一生比作一支长曲里的一个音符,终将融入整体和声。✓ one note in music."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',8,NULL,'choice','{"stem":"How does the speaker wish to die?","options":["Still at work, knowing others will carry on","Fearful and bitter","In complete idleness","Far from everyone"],"answer_index":0,"explanation_cn":"录音说讲述者愿工作到最后一刻,知道别人会接着完成他做不了的事。✓ die at work, others carry on."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',9,NULL,'choice','{"stem":"你想说\"害怕死于战场的年轻人可能感到痛苦\"(who 引导,指人):","options":["A young man who fear death in battle may feel bitter.","A young man which fears death in battle may feel bitter.","A young man he fears death in battle may feel bitter.","A young man who fears death in battle may feel bitter."],"answer_index":3,"explanation_cn":"who 引导、指人;后面动词随所指的人用 fears、不能用 which(指物)、不用原形 fear、也不能再加 he 重复。✓ A young man who fears… 场合:说“…的人”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',9,NULL,'choice','{"stem":"你想说\"他不会惧怕死亡,因为他所关心的事会延续\"(since 原因):","options":["He will not fear death, since the things he cares for will continue.","He will not fear death, unless the things he cares for will continue.","He will not fear death, since the things he care for will continue.","He will not fear death, since the things he cares for will continuing."],"answer_index":0,"explanation_cn":"since 表原因“因为”;continue 用 will continue、不写成 continuing、cares 随第三人称单数;换成 unless 意思就反了。✓ since the things he cares for will continue. 场合:说“…,因为…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',9,NULL,'choice','{"stem":"你想说\"如果疲惫加深,休息的念头便受欢迎\"(if 条件):","options":["Unless weariness increases, the thought of rest is welcome.","If weariness increase, the thought of rest is welcome.","If weariness increases, the thought of rest is welcome.","If weariness increases, the thought of rest are welcome."],"answer_index":2,"explanation_cn":"if 引导条件;从句用一般现在 increases(随单数 weariness)、主句 is 用单数;换成 unless 意思相反。✓ If weariness increases, the thought of rest is welcome. 场合:说“如果…,就…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"oppress 的意思是:","options":["赞美","解放","压迫,使烦恼","取悦"],"answer_index":2,"explanation_cn":"oppress = 压迫、使烦恼。✓ oppressed by the fear of death."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"vitality 的意思是:","options":["沉默","活力,生命力","黑暗","疲惫"],"answer_index":1,"explanation_cn":"vitality = 活力、生命力。✓ as his vitality decays."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"\"A young man ___ fears death may feel bitter.\"(定语从句,指人)","options":["whose","which","what","who"],"answer_index":3,"stem_cn":"害怕死亡的年轻人可能感到痛苦。","explanation_cn":"定语从句指人(a young man)作主语,用 who。✓ A young man who fears death. ✗ which / what / whose。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"\"Others will carry on ___ he can no longer do.\"(名词从句,‘所…的事’)","options":["how","which","what","that"],"answer_index":2,"stem_cn":"别人会接着做他再也做不了的事。","explanation_cn":"名词从句“所…的事”,用 what。✓ carry on what he can no longer do. ✗ that / which / how。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"\"carry on\" 的意思是:","options":["停止","继续(做)","抱怨","携带走"],"answer_index":1,"explanation_cn":"carry on = 继续(做)。✓ Others will carry on my work."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"\"little by little\" 的意思是:","options":["一点一点地、逐渐地","突然地","完全地","很少地"],"answer_index":0,"explanation_cn":"little by little = 一点一点地、逐渐地。✓ little by little the walls recede."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"According to the passage, why is the fear of death abject in an old man?","options":["He is still very young","He has never enjoyed life","He fears battle","He has already known life''s joys and sorrows and done his work"],"answer_index":3,"passage":"Some old people are worn down by the fear of death. In the young this dread has a real justification: a young man who has good reason to fear he may be killed before his time can justifiably feel bitter, for he has been robbed of the best that life had to offer. But in someone who has lived long, who has known deep joys and heavy sorrows, and who has finished whatever work it was given him to do, the same fear seems to me abject and ignoble. The surest way to overcome it is this: let your interests grow gradually wider and more impersonal, until, little by little, the walls of the ego begin to recede and your own small life is taken up into something far larger. A single human life should be like one note in a long piece of music. At first the note sounds alone, anxious and eager, singing passionately of itself. But as the music goes on, the note is joined by others; it is no longer heard as one lonely sound but as part of a great harmony, and in the end it fades painlessly into the whole without any sense of loss. Whoever, in old age, can hear his own life in this way will not be oppressed by the fear of death, since the things he has cared for will go on after him. And if, as his vitality decays, weariness gradually increases, the thought of rest will not be unwelcome. For my part, I should wish to keep working to the last, knowing that others will carry on what I can no longer do, and glad in the thought that what was possible for me has indeed been done.","explanation_cn":"课文说老人已尝过人生的悲欢、又做完了该做的工作,所以此时再怕死就显得凄惨卑下。✓ known joys and sorrows, done his work."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"What does the passage say happens as your interests grow wider and more impersonal?","options":["The walls of the ego recede and your life merges into something larger","You lose all your friends","You stop caring about anything","You become selfish"],"answer_index":0,"passage":"Some old people are worn down by the fear of death. In the young this dread has a real justification: a young man who has good reason to fear he may be killed before his time can justifiably feel bitter, for he has been robbed of the best that life had to offer. But in someone who has lived long, who has known deep joys and heavy sorrows, and who has finished whatever work it was given him to do, the same fear seems to me abject and ignoble. The surest way to overcome it is this: let your interests grow gradually wider and more impersonal, until, little by little, the walls of the ego begin to recede and your own small life is taken up into something far larger. A single human life should be like one note in a long piece of music. At first the note sounds alone, anxious and eager, singing passionately of itself. But as the music goes on, the note is joined by others; it is no longer heard as one lonely sound but as part of a great harmony, and in the end it fades painlessly into the whole without any sense of loss. Whoever, in old age, can hear his own life in this way will not be oppressed by the fear of death, since the things he has cared for will go on after him. And if, as his vitality decays, weariness gradually increases, the thought of rest will not be unwelcome. For my part, I should wish to keep working to the last, knowing that others will carry on what I can no longer do, and glad in the thought that what was possible for me has indeed been done.","explanation_cn":"课文说随着兴趣变得更宽广、更超脱个人,自我的高墙渐渐后退,一生融入某种更宏大的东西。✓ ego recedes, life merges into something larger."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"What does the speaker compare a human life to?","options":["A stone in a wall","A candle in the wind","A ship at sea","A single note in a long piece of music"],"answer_index":3,"audio":"Some old people are worn down by the fear of death. In the young this dread has a real justification: a young man who has good reason to fear he may be killed before his time can justifiably feel bitter, for he has been robbed of the best that life had to offer. But in someone who has lived long, who has known deep joys and heavy sorrows, and who has finished whatever work it was given him to do, the same fear seems to me abject and ignoble. The surest way to overcome it is this: let your interests grow gradually wider and more impersonal, until, little by little, the walls of the ego begin to recede and your own small life is taken up into something far larger. A single human life should be like one note in a long piece of music. At first the note sounds alone, anxious and eager, singing passionately of itself. But as the music goes on, the note is joined by others; it is no longer heard as one lonely sound but as part of a great harmony, and in the end it fades painlessly into the whole without any sense of loss. Whoever, in old age, can hear his own life in this way will not be oppressed by the fear of death, since the things he has cared for will go on after him. And if, as his vitality decays, weariness gradually increases, the thought of rest will not be unwelcome. For my part, I should wish to keep working to the last, knowing that others will carry on what I can no longer do, and glad in the thought that what was possible for me has indeed been done.","explanation_cn":"课文把一个人的一生比作长曲中的一个音符,最终毫无痛苦地融入整体和声。✓ one note in music."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l11',10,NULL,'choice','{"stem":"How does the speaker feel about others continuing his work?","options":["Frightened","Content, knowing what was possible has been done","Bitter and resentful","Completely indifferent"],"answer_index":1,"audio":"Some old people are worn down by the fear of death. In the young this dread has a real justification: a young man who has good reason to fear he may be killed before his time can justifiably feel bitter, for he has been robbed of the best that life had to offer. But in someone who has lived long, who has known deep joys and heavy sorrows, and who has finished whatever work it was given him to do, the same fear seems to me abject and ignoble. The surest way to overcome it is this: let your interests grow gradually wider and more impersonal, until, little by little, the walls of the ego begin to recede and your own small life is taken up into something far larger. A single human life should be like one note in a long piece of music. At first the note sounds alone, anxious and eager, singing passionately of itself. But as the music goes on, the note is joined by others; it is no longer heard as one lonely sound but as part of a great harmony, and in the end it fades painlessly into the whole without any sense of loss. Whoever, in old age, can hear his own life in this way will not be oppressed by the fear of death, since the things he has cared for will go on after him. And if, as his vitality decays, weariness gradually increases, the thought of rest will not be unwelcome. For my part, I should wish to keep working to the last, knowing that others will carry on what I can no longer do, and glad in the thought that what was possible for me has indeed been done.","explanation_cn":"课文说讲述者欣慰地想到:凡是力所能及的都已做成,别人会继续其余。✓ content, what was possible has been done."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l12',4,2,12,'Banks and Their Customers','银行和顾客','介词 + 关系代词(the repayment of which…)、whether … or … 引导的从句、同位语从句 that(a rule/the fact that…)、情态动词 + have done 对过去的推测(may/must/can''t have been)、tell/instruct sb to do + 过去分词作定语(checks drawn by himself)(NCE4 无 KS 页,考点由课文结构自取;IP:源为消费者法著作,内容为通用银行法概念(事实性、不可版权),已用 100% 原创行文复述,无人物;题材=银行与客户的法律关系·无害;美语化 check/favor;第四册第12课·第二册收官课)','当一个人在银行开立活期账户,多数人以为自己不过是把钱交去保管。法律上的真相却更古怪:客户其实是在把钱借给银行,于是银行成了债务人——这笔债的偿还,他可以随时要求,或取现金,或开一张支票付给别人。因此,银行与客户之间最根本的关系,是债务人与债权人的关系;至于谁是哪一方,取决于账户是有余额还是透支。不过,除了这个简单的概念,双方还彼此负有一整套义务,其中许多会招来麻烦与纠葛。然而,银行客户不同于——比方说——普通的买货人,他很少能抱怨法律对自己不公。银行必须听从它客户的指示,而不听任何别人的。当一个人头一回开户,他会吩咐银行只为他本人开出的支票扣款,并留下几份签名样本,好让职员比对。有一条极硬的规矩:凡是签名被伪造的支票,银行无权动用客户的钱去兑付。哪怕那伪造也许曾极其高明,也毫无分别:银行仍被要求认得自己客户的笔迹。正因如此,银行如今普遍采用的、把客户姓名印在其支票上的做法,对客户其实并无风险。即便这一习惯当真便利了某次伪造,承担损失的也是银行,而非客户。','{"q":"Listen and answer — Why is there no risk to the customer when a bank prints the customer''s name on his checks?","options":["Because the bank, not the customer, must bear any loss from forgery","Because printed names can never be forged","Because the customer pays extra insurance","Because the bank ignores all signatures"],"answer_index":0}'::jsonb,'{"title":"介词+关系代词 / whether…or / 同位语从句 / 情态+have done / tell sb to do","intro":"①介词 + 关系代词:the repayment of which he may demand;the account on which he draws checks。②whether … or …:depends on whether the account is in credit or overdrawn。③同位语从句 that,解释前面抽象名词:a rule that the bank must recognize the signature。④情态词 + have + 过去分词,对过去推测:may have been / must have been / can''t have been。⑤tell/instruct sb to do;过去分词作定语:checks drawn by himself。","table":{"headers":["用法","结构","例子"],"rows":[["介词+关系代词","介词 + which/whom","the repayment of which he may demand"],["whether…or","whether A or B","whether it is in credit or overdrawn"],["同位语从句","名词 + that + 句子","a rule that the bank must recognize it"],["情态+have done","may/must + have + 过去分词","the forgery may have been clever"],["过去分词作定语","名词 + done","checks drawn by himself"]]},"specialRules":[{"rule":"情态词 + have + 过去分词表示对过去的推测:may have(也许曾)、must have(一定曾)、can''t have(不可能曾)。","mark":"may/must/can''t + have + done"},{"rule":"同位语从句用 that 引导且 that 不作成分(不可省、不能换 which);定语从句里 that 要在从句中充当成分。","mark":"同位语 that ≠ 定语 that"},{"rule":"美式拼写:check(支票,英式 cheque)、favor(有利,英式 favour)。本课已按美语写。","mark":"check / favor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l12',1,NULL,'When a person opens a current account at a bank, most people imagine they are simply handing their money over for safekeeping. In law the truth is stranger: the customer is actually lending money to the bank, so that the bank becomes a debtor — a debt the repayment of which he may demand at any moment, either in cash or by writing a check in favor of someone else.','当一个人在银行开立活期账户,多数人以为自己不过是把钱交去保管。法律上的真相却更古怪:客户其实是在把钱借给银行,于是银行成了债务人——这笔债的偿还,他可以随时要求,或取现金,或开一张支票付给别人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l12',2,NULL,'The basic tie between a bank and its customer is therefore that of debtor and creditor, and who is which depends on whether the account is in credit or is overdrawn. Beyond that simple idea, however, the two owe each other a whole set of obligations, and many of these can lead to problems and complications.','因此,银行与客户之间最根本的关系,是债务人与债权人的关系;至于谁是哪一方,取决于账户是有余额还是透支。不过,除了这个简单的概念,双方还彼此负有一整套义务,其中许多会招来麻烦与纠葛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l12',3,NULL,'Yet a bank customer, unlike, say, an ordinary buyer of goods, can rarely complain that the law is stacked against him. The bank must obey its customer''s instructions, and no one else''s. When someone first opens an account, he tells the bank to debit it only for checks drawn by himself, and he leaves specimens of his signature so that the staff can compare them.','然而,银行客户不同于——比方说——普通的买货人,他很少能抱怨法律对自己不公。银行必须听从它客户的指示,而不听任何别人的。当一个人头一回开户,他会吩咐银行只为他本人开出的支票扣款,并留下几份签名样本,好让职员比对。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l12',4,NULL,'There is a very firm rule that the bank has no right to pay out a customer''s money on a check whose signature has been forged. It makes no difference that the forgery may have been an extremely clever one: the bank is still expected to recognize its own customer''s hand.','有一条极硬的规矩:凡是签名被伪造的支票,银行无权动用客户的钱去兑付。哪怕那伪造也许曾极其高明,也毫无分别:银行仍被要求认得自己客户的笔迹。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l12',5,NULL,'For this reason there is really no danger to the customer in the practice, now widely adopted by banks, of printing the customer''s name on his checks. Even if that habit should happen to facilitate a forgery, it is the bank, and not the customer, that must bear the loss.','正因如此,银行如今普遍采用的、把客户姓名印在其支票上的做法,对客户其实并无风险。即便这一习惯当真便利了某次伪造,承担损失的也是银行,而非客户。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l12','current','/ˈkɜːrənt/','adj','活期的,现行的','opens a current account') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l12','account','/əˈkaʊnt/','n','账户','a current account at a bank') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l12','debtor','/ˈdetər/','n','债务人,借方','the bank becomes a debtor') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
