INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l12','favor','favour','有利/恩惠;拼写差异,美语 favor') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l12','license','licence','执照;美语名词动词都用 license') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
