INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l12','in favor of','',NULL,'/ɪn ˈfeɪvər əv/','He wrote a check in favor of his landlord.','他开了一张支票付给房东。','The court ruled in favor of the customer.','法院判决对客户有利。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l12','pay out','',NULL,'/peɪ aʊt/','The bank may not pay out on a forged check.','银行不得凭伪造的支票付款。','They paid out the full amount.','他们付清了全额。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l12','make no difference','',NULL,'/meɪk noʊ ˈdɪfrəns/','It makes no difference that the forgery was clever.','伪造再高明也毫无分别。','Your excuse makes no difference now.','你的借口现在无关紧要。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l12','bear the loss','',NULL,'/ber ðə lɔːs/','The bank must bear the loss.','银行必须承担损失。','Who will bear the cost?','谁来承担这笔费用?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp1','choice','{"stem":"\"It is a debt the repayment ___ which he may demand at any time.\"(介词+关系代词,‘其偿还’,填介词)","options":["on","at","for","of"],"answer_index":3,"stem_cn":"这是一笔他可随时要求偿还的债。","explanation_cn":"介词 + 关系代词:the repayment of which=“其偿还”;表所属关系用 of。✓ the repayment of which he may demand. ✗ on / at / for:表“其…”用 of。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp1','choice','{"stem":"\"The account ___ which he draws checks is a current one.\"(介词+关系代词;开支票所凭的账户,填与 draw 搭配的介词)","options":["of","on","at","in"],"answer_index":1,"stem_cn":"他开支票所凭的那个账户是活期账户。","explanation_cn":"介词 + 关系代词:draw checks on an account(在某账户上开支票),故介词提前用 on。✓ the account on which he draws checks. ✗ of / at / in:与 draw 搭配用 on。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp1','choice','{"stem":"\"The rule ___ which the bank acts protects the customer.\"(介词+关系代词;银行依据的规则,填与 act 搭配的介词)","options":["of","for","at","on"],"answer_index":3,"stem_cn":"银行依据的那条规则保护着客户。","explanation_cn":"介词 + 关系代词:act on a rule(依据规则行事),故介词提前用 on。✓ the rule on which the bank acts. ✗ of / at / for:与 act 搭配用 on。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp2','choice','{"stem":"\"Who is which depends on ___ the account is in credit or overdrawn.\"(‘是否/…还是…’,填连词)","options":["that","which","whether","what"],"answer_index":2,"stem_cn":"谁是谁,取决于账户是有余额还是透支。","explanation_cn":"“是否/…还是…”引导从句,用 whether。✓ depends on whether the account is in credit or overdrawn. ✗ that / which / what:表“是否”用 whether。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp2','choice','{"stem":"\"The bank must check ___ the signature is genuine or forged.\"(‘是否…’,填连词)","options":["unless","whether","if only","that"],"answer_index":1,"stem_cn":"银行必须核查签名是真是假。","explanation_cn":"“是否…”引导从句,用 whether。✓ check whether the signature is genuine or forged. ✗ that / if only / unless:表“是否”用 whether。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp2','choice','{"stem":"\"It matters little ___ the forgery is clumsy or skilful.\"(‘无论…还是…’,填连词)","options":["unless","since","though","whether"],"answer_index":3,"stem_cn":"伪造是拙劣还是高明,都无关紧要。","explanation_cn":"“无论…还是…”引导从句,用 whether。✓ whether the forgery is clumsy or skilful. ✗ though / since / unless:表“无论…还是”用 whether。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp3','choice','{"stem":"\"There is a firm rule ___ the bank must recognize its customer''s signature.\"(同位语从句,解释 rule 的内容,填连词)","options":["which","that","what","whether"],"answer_index":1,"stem_cn":"有一条硬规矩:银行必须认得客户的签名。","explanation_cn":"同位语从句,解释抽象名词 rule 的内容,用 that(不作成分、不可省)。✓ a firm rule that the bank must recognize the signature. ✗ which / what / whether:同位语从句用 that。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp3','choice','{"stem":"\"The fact ___ the account is overdrawn changes who owes whom.\"(同位语从句,解释 fact,填连词)","options":["which","what","that","it"],"answer_index":2,"stem_cn":"账户透支这一事实,改变了谁欠谁。","explanation_cn":"同位语从句,解释 fact 的内容,用 that。✓ The fact that the account is overdrawn. ✗ which / what / it:同位语从句用 that。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp3','choice','{"stem":"\"He accepts the idea ___ he is lending the bank money.\"(同位语从句,解释 idea,填连词)","options":["that","which","whether","what"],"answer_index":0,"stem_cn":"他接受了这样一个观念:他是在借钱给银行。","explanation_cn":"同位语从句,解释 idea 的内容,用 that。✓ the idea that he is lending the bank money. ✗ which / what / whether:同位语从句用 that。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp4','choice','{"stem":"\"The forgery may ___ been a very clever one.\"(may + ___ + 过去分词,对过去的推测,填中间的助动词)","options":["having","have","had","has"],"answer_index":1,"stem_cn":"那伪造也许曾是非常高明的。","explanation_cn":"情态词 + have + 过去分词,对过去推测;may 后接 have。✓ The forgery may have been clever. ✗ has / had / having:情态词后一律用 have。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp4','choice','{"stem":"\"The clerk must ___ missed the forged signature.\"(must + ___ + 过去分词,对过去的肯定推测,填中间的助动词)","options":["had","has","have","be"],"answer_index":2,"stem_cn":"那职员一定是漏看了伪造的签名。","explanation_cn":"must + have + 过去分词,对过去的肯定推测。✓ The clerk must have missed it. ✗ has / had / be:情态词后用 have。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp4','choice','{"stem":"\"He can''t ___ signed it, for he was abroad.\"(can''t + ___ + 过去分词,对过去的否定推测,填中间的助动词)","options":["have","had","being","has"],"answer_index":0,"stem_cn":"他不可能签过字,因为他当时在国外。","explanation_cn":"can''t + have + 过去分词,对过去的否定推测。✓ He can''t have signed it. ✗ has / had / being:情态词后用 have。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp5','choice','{"stem":"\"He tells the bank ___ his account only for his own checks.\"(tell sb 后接不定式;‘吩咐银行扣款’,填正确形式)","options":["debiting","to debit","debit","debited"],"answer_index":1,"stem_cn":"他吩咐银行只为他本人的支票扣款。","explanation_cn":"tell sb 后接不定式:tell the bank to do。✓ He tells the bank to debit his account. ✗ debit / debiting / debited:tell sb 后用不定式。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp5','choice','{"stem":"\"The bank may pay only checks ___ by the customer himself.\"(过去分词作定语,‘由…开出的’;draw 的过去分词)","options":["to draw","drawing","draw","drawn"],"answer_index":3,"stem_cn":"银行只能支付客户本人开出的支票。","explanation_cn":"过去分词作定语,表被动“由…开出的”;draw 的过去分词 drawn。✓ checks drawn by the customer himself. ✗ drawing(主动)/ draw / to draw:被动定语用过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp5','choice','{"stem":"\"The name ___ on his checks does not put him at risk.\"(过去分词作定语,‘印在…上的’;print 的过去分词)","options":["printed","to print","print","printing"],"answer_index":0,"stem_cn":"印在支票上的姓名不会使他有风险。","explanation_cn":"过去分词作定语,表被动“印在…上的”;print 的过去分词 printed。✓ the name printed on his checks. ✗ printing(主动)/ print / to print:被动定语用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp6','choice','{"stem":"\"A person or bank that owes money is a ___.\"(“债务人、借方”用哪个词)","options":["seller","creditor","buyer","debtor"],"answer_index":3,"stem_cn":"欠着钱的一方。","explanation_cn":"欠着钱的一方是 debtor(债务人)。✓ a bank that owes money is a debtor. ✗ creditor 债权人;✗ buyer 买主;✗ seller 卖主——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp6','choice','{"stem":"\"To copy a signature falsely in order to cheat is to ___ it.\"(“伪造”用哪个词)","options":["print","forge","keep","sign"],"answer_index":1,"stem_cn":"为行骗而假冒签名。","explanation_cn":"为行骗而假冒签名是 forge(伪造)。✓ to copy a signature falsely is to forge it. ✗ sign 签署;✗ print 印刷;✗ keep 保留——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',5,'am4_l12_gp6','choice','{"stem":"\"To take up and start using a practice is to ___ it.\"(“采用、采纳”用哪个词)","options":["forget","hide","refuse","adopt"],"answer_index":3,"stem_cn":"接受并开始采用某种做法。","explanation_cn":"接受并开始采用某做法是 adopt(采用)。✓ to take up a practice is to adopt it. ✗ refuse 拒绝;✗ forget 忘记;✗ hide 隐藏——都相反或不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',6,NULL,'choice','{"stem":"debtor 的意思是:","options":["证人","买主","债主","债务人,借方"],"answer_index":3,"explanation_cn":"debtor = 债务人、借方。✓ the bank becomes a debtor."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',6,NULL,'choice','{"stem":"creditor 的意思是:","options":["顾客","债务人","债权人,债主","职员"],"answer_index":2,"explanation_cn":"creditor = 债权人、债主。✓ the relationship of debtor and creditor."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',6,NULL,'choice','{"stem":"obligation 的意思是:","options":["权利","义务,责任","礼物","假期"],"answer_index":1,"explanation_cn":"obligation = 义务、责任。✓ a whole set of obligations."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',6,NULL,'choice','{"stem":"forge 的意思是:","options":["购买","签署","储存","伪造"],"answer_index":3,"explanation_cn":"forge = 伪造。✓ a signature that has been forged."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',6,NULL,'choice','{"stem":"facilitate 的意思是:","options":["使便利,促进","推迟","禁止","阻碍"],"answer_index":0,"explanation_cn":"facilitate = 使便利、促进。✓ should happen to facilitate a forgery."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',6,NULL,'choice','{"stem":"specimen 的意思是:","options":["命令","样本,样品","罚款","收据"],"answer_index":1,"explanation_cn":"specimen = 样本、样品。✓ leaves specimens of his signature."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',7,NULL,'cloze','{"stem":"第 1 空","context":"When you open a current account, you are lending the bank money, the repayment ___1___ which you may demand at any time. Whether you are creditor or debtor depends ___2___ whether your account is in credit. There is a firm rule ___3___ the bank must not pay a forged check. It makes no difference ___4___ the forgery is clever.","blank_no":1,"options":["of","on","at","for"],"answer_index":0,"explanation_cn":"介词 + 关系代词:the repayment of which,‘其偿还’,用 of。✓ the repayment of which you may demand."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',7,NULL,'cloze','{"stem":"第 2 空","context":"When you open a current account, you are lending the bank money, the repayment ___1___ which you may demand at any time. Whether you are creditor or debtor depends ___2___ whether your account is in credit. There is a firm rule ___3___ the bank must not pay a forged check. It makes no difference ___4___ the forgery is clever.","blank_no":2,"options":["on","of","at","in"],"answer_index":0,"explanation_cn":"depend on whether,‘取决于是否’;介词用 on。✓ depends on whether your account is in credit."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',7,NULL,'cloze','{"stem":"第 3 空","context":"When you open a current account, you are lending the bank money, the repayment ___1___ which you may demand at any time. Whether you are creditor or debtor depends ___2___ whether your account is in credit. There is a firm rule ___3___ the bank must not pay a forged check. It makes no difference ___4___ the forgery is clever.","blank_no":3,"options":["that","which","what","whether"],"answer_index":0,"explanation_cn":"同位语从句,解释 rule 的内容,用 that。✓ a firm rule that the bank must not pay a forged check."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',7,NULL,'cloze','{"stem":"第 4 空","context":"When you open a current account, you are lending the bank money, the repayment ___1___ which you may demand at any time. Whether you are creditor or debtor depends ___2___ whether your account is in credit. There is a firm rule ___3___ the bank must not pay a forged check. It makes no difference ___4___ the forgery is clever.","blank_no":4,"options":["that","which","what","whether"],"answer_index":0,"explanation_cn":"that 引导从句,‘伪造再高明也没影响’;It makes no difference that…。✓ It makes no difference that the forgery is clever."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',8,NULL,'choice','{"stem":"Why is there no risk to the customer when a bank prints his name on his checks?","options":["The bank must bear the loss if a forged check is paid","Printed names cannot be forged","The bank never checks signatures","The customer must pay for any forgery"],"answer_index":0,"explanation_cn":"录音说银行无权凭伪造签名付款,若照付,损失由银行承担,故印名字对客户无风险。✓ bank bears the loss."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',8,NULL,'choice','{"stem":"What is the basic legal relationship between a bank and its customer?","options":["Teacher and student","Landlord and tenant","Debtor and creditor","Buyer and seller"],"answer_index":2,"explanation_cn":"录音说银行与客户之间最根本的法律关系是债务人与债权人的关系。✓ debtor and creditor."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',8,NULL,'choice','{"stem":"Whose instructions must the bank obey?","options":["The government''s only","The largest depositor''s","Anyone who asks","Only its own customer''s"],"answer_index":3,"explanation_cn":"录音说银行必须只听从它自己客户的指示,而不听任何别人的。✓ only its own customer''s instructions."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',9,NULL,'choice','{"stem":"你想说\"谁是谁取决于账户是有余额还是透支\"(whether…or):","options":["Who is which depends on whether the account is in credit or overdrawn.","Who is which depends on whether the account is in credit or overdrawn or.","Who is which depends whether the account is in credit or overdrawn.","Who is which depends on that the account is in credit or overdrawn."],"answer_index":0,"explanation_cn":"depends on whether … or …,‘取决于是…还是…’;用 whether 不用 that、句末不多加 or、depends 后不能省 on。✓ depends on whether … or overdrawn. 场合:说“取决于是…还是…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',9,NULL,'choice','{"stem":"你想说\"有一条硬规矩:银行必须认得客户的签名\"(同位语从句 that):","options":["There is a firm rule what the bank must recognize its customer''s signature.","There is a firm rule which the bank must recognize its customer''s signature.","There is a firm rule that the bank must recognize its customer''s signature.","There is a firm rule that the bank must recognizes its customer''s signature."],"answer_index":2,"explanation_cn":"同位语从句用 that 引导、解释 rule 的内容;不用 which、不用 what;must 后动词用原形 recognize(不加 -s)。✓ a firm rule that the bank must recognize… 场合:说“有一条规矩:…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',9,NULL,'choice','{"stem":"你想说\"那伪造也许曾是非常高明的\"(may have done 对过去推测):","options":["The forgery may have be a very clever one.","The forgery may has been a very clever one.","The forgery may had been a very clever one.","The forgery may have been a very clever one."],"answer_index":3,"explanation_cn":"情态词 + have + 过去分词表对过去的推测;may 后用 have(不用 has/had)、been 不写成 be。✓ may have been. 场合:说“也许曾…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"debtor 的意思是:","options":["证人","债主","债务人,借方","买主"],"answer_index":2,"explanation_cn":"debtor = 债务人、借方。✓ the bank becomes a debtor."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"forge 的意思是:","options":["伪造","签署","购买","储存"],"answer_index":0,"explanation_cn":"forge = 伪造。✓ a signature that has been forged."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"\"It is a debt the repayment ___ which he may demand at any time.\"(介词+关系代词)","options":["on","at","for","of"],"answer_index":3,"stem_cn":"这是一笔他可随时要求偿还的债。","explanation_cn":"介词 + 关系代词:the repayment of which,‘其偿还’,用 of。✓ the repayment of which he may demand. ✗ on / at / for。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"\"The forgery may ___ been a very clever one.\"(may + ___ + 过去分词)","options":["had","have","having","has"],"answer_index":1,"stem_cn":"那伪造也许曾是非常高明的。","explanation_cn":"情态词 + have + 过去分词,对过去推测;may 后用 have。✓ The forgery may have been clever. ✗ has / had / having。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"\"in favor of\" 的意思是:","options":["由于","反对","除了","有利于、支付给"],"answer_index":3,"explanation_cn":"in favor of = 有利于、支付给(某人)。✓ a check in favor of his landlord."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"\"make no difference\" 的意思是:","options":["没有影响、无关紧要","制造分歧","犯错误","找零钱"],"answer_index":0,"explanation_cn":"make no difference = 没有影响、无关紧要。✓ It makes no difference that the forgery was clever."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"According to the passage, what does opening a current account actually mean in law?","options":["The bank owns the customer''s money outright","The customer is buying shares in the bank","The customer is lending money to the bank","The bank is giving the customer a gift"],"answer_index":2,"passage":"When a person opens a current account at a bank, most people imagine they are simply handing their money over for safekeeping. In law the truth is stranger: the customer is actually lending money to the bank, so that the bank becomes a debtor — a debt the repayment of which he may demand at any moment, either in cash or by writing a check in favor of someone else. The basic tie between a bank and its customer is therefore that of debtor and creditor, and who is which depends on whether the account is in credit or is overdrawn. Beyond that simple idea, however, the two owe each other a whole set of obligations, and many of these can lead to problems and complications. Yet a bank customer, unlike, say, an ordinary buyer of goods, can rarely complain that the law is stacked against him. The bank must obey its customer''s instructions, and no one else''s. When someone first opens an account, he tells the bank to debit it only for checks drawn by himself, and he leaves specimens of his signature so that the staff can compare them. There is a very firm rule that the bank has no right to pay out a customer''s money on a check whose signature has been forged. It makes no difference that the forgery may have been an extremely clever one: the bank is still expected to recognize its own customer''s hand. For this reason there is really no danger to the customer in the practice, now widely adopted by banks, of printing the customer''s name on his checks. Even if that habit should happen to facilitate a forgery, it is the bank, and not the customer, that must bear the loss.","explanation_cn":"课文说开活期账户在法律上其实是把钱借给银行,银行成了债务人。✓ lending money to the bank."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"Why is there no risk to the customer if a bank prints his name on his checks?","options":["The bank, not the customer, bears the loss from any forgery","The customer signs twice","The law favors the bank","The printed name cannot be copied"],"answer_index":0,"passage":"When a person opens a current account at a bank, most people imagine they are simply handing their money over for safekeeping. In law the truth is stranger: the customer is actually lending money to the bank, so that the bank becomes a debtor — a debt the repayment of which he may demand at any moment, either in cash or by writing a check in favor of someone else. The basic tie between a bank and its customer is therefore that of debtor and creditor, and who is which depends on whether the account is in credit or is overdrawn. Beyond that simple idea, however, the two owe each other a whole set of obligations, and many of these can lead to problems and complications. Yet a bank customer, unlike, say, an ordinary buyer of goods, can rarely complain that the law is stacked against him. The bank must obey its customer''s instructions, and no one else''s. When someone first opens an account, he tells the bank to debit it only for checks drawn by himself, and he leaves specimens of his signature so that the staff can compare them. There is a very firm rule that the bank has no right to pay out a customer''s money on a check whose signature has been forged. It makes no difference that the forgery may have been an extremely clever one: the bank is still expected to recognize its own customer''s hand. For this reason there is really no danger to the customer in the practice, now widely adopted by banks, of printing the customer''s name on his checks. Even if that habit should happen to facilitate a forgery, it is the bank, and not the customer, that must bear the loss.","explanation_cn":"课文说银行无权凭伪造签名付款,若因印名字便利了伪造,承担损失的是银行而非客户。✓ bank bears the loss."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"Whose instructions must the bank obey?","options":["The government''s","Anyone who walks in","The biggest account holder''s","Only its own customer''s"],"answer_index":3,"audio":"When a person opens a current account at a bank, most people imagine they are simply handing their money over for safekeeping. In law the truth is stranger: the customer is actually lending money to the bank, so that the bank becomes a debtor — a debt the repayment of which he may demand at any moment, either in cash or by writing a check in favor of someone else. The basic tie between a bank and its customer is therefore that of debtor and creditor, and who is which depends on whether the account is in credit or is overdrawn. Beyond that simple idea, however, the two owe each other a whole set of obligations, and many of these can lead to problems and complications. Yet a bank customer, unlike, say, an ordinary buyer of goods, can rarely complain that the law is stacked against him. The bank must obey its customer''s instructions, and no one else''s. When someone first opens an account, he tells the bank to debit it only for checks drawn by himself, and he leaves specimens of his signature so that the staff can compare them. There is a very firm rule that the bank has no right to pay out a customer''s money on a check whose signature has been forged. It makes no difference that the forgery may have been an extremely clever one: the bank is still expected to recognize its own customer''s hand. For this reason there is really no danger to the customer in the practice, now widely adopted by banks, of printing the customer''s name on his checks. Even if that habit should happen to facilitate a forgery, it is the bank, and not the customer, that must bear the loss.","explanation_cn":"课文说银行必须只听从自己客户的指示,而不听任何别人的。✓ only its own customer''s."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l12',10,NULL,'choice','{"stem":"What must the bank do with a forged signature?","options":["Refuse to pay, and bear the loss if it does","Ignore the rule","Report the customer","Pay it and charge the customer"],"answer_index":0,"audio":"When a person opens a current account at a bank, most people imagine they are simply handing their money over for safekeeping. In law the truth is stranger: the customer is actually lending money to the bank, so that the bank becomes a debtor — a debt the repayment of which he may demand at any moment, either in cash or by writing a check in favor of someone else. The basic tie between a bank and its customer is therefore that of debtor and creditor, and who is which depends on whether the account is in credit or is overdrawn. Beyond that simple idea, however, the two owe each other a whole set of obligations, and many of these can lead to problems and complications. Yet a bank customer, unlike, say, an ordinary buyer of goods, can rarely complain that the law is stacked against him. The bank must obey its customer''s instructions, and no one else''s. When someone first opens an account, he tells the bank to debit it only for checks drawn by himself, and he leaves specimens of his signature so that the staff can compare them. There is a very firm rule that the bank has no right to pay out a customer''s money on a check whose signature has been forged. It makes no difference that the forgery may have been an extremely clever one: the bank is still expected to recognize its own customer''s hand. For this reason there is really no danger to the customer in the practice, now widely adopted by banks, of printing the customer''s name on his checks. Even if that habit should happen to facilitate a forgery, it is the bank, and not the customer, that must bear the loss.","explanation_cn":"课文说凡签名被伪造的支票银行无权兑付;若照付,损失自负。✓ refuse to pay, bear the loss."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
